/* Exact local source identities; uploaded office documents never leave the browser. */
(function(root){'use strict';
 const cache=new Map(),pending=new Map(),office=/\.(?:xlsx?|docx?)$/i,temporary=n=>n.split('/').some(x=>/^~\$|^\.~|^~lock\./i.test(x)),phase=n=>n==='二、执行一般审计程序.zip'?6:n==='一、执行实质性程序.zip'?7:/^1[、.\s]/.test(n)?3:/^2[、.\s]/.test(n)?4:5;
 const validEntry=e=>!e.name.startsWith('__MACOSX/')&&!e.name.split('/').some(x=>x.startsWith('._')||x==='.DS_Store')&&!e.name.endsWith('/')&&office.test(e.name)&&!temporary(e.name);
 function descriptors(record){const out=[],seen=new Set();for(const value of Object.values(record.workpaperSources||{}))if(value?.archive){const a=value.archive;if(!seen.has(a.hash)){out.push({archive:a,index:value.index||[],phase:value.phase});seen.add(a.hash);}}for(const pair of [[record.archive,record.index,3],[record.riskArchive,record.riskIndex,4]])if(pair[0]&&!seen.has(pair[0].hash)){out.push({archive:pair[0],index:pair[1]||[],phase:pair[2]});seen.add(pair[0].hash);}return out;}
 async function inspect(archive){const S=root.ProjectWorkspaceStore,actual=await S.hash(archive.blob);if(archive.hash&&archive.hash!==actual)throw Error('原包哈希不一致，请先下载备份，未替换或套用底稿。');if(cache.has(actual))return cache.get(actual);const result=(async()=>{const a=await root.BidderArchive.open(new File([archive.blob],archive.name),{entryLimit:2048});try{const entries=a.entries.filter(validEntry);if(entries.length>512)throw Error('原包有效文件超过512份');const index=[];for(let i=0;i<entries.length;i+=8){const got=await a.read(entries.slice(i,i+8).map(e=>e.name));for(const e of entries.slice(i,i+8)){const bytes=got.get(e.name),sha256=await S.hash(new Blob([bytes]));index.push({name:e.name,path:e.name,size:bytes.length,sha256});}}return{archiveHash:actual,index,ignoredTemporary:a.entries.filter(e=>office.test(e.name)&&temporary(e.name)).map(e=>e.name)};}finally{a.close();}})();cache.set(actual,result);try{return await result;}catch(e){cache.delete(actual);throw e;}}
 async function prepare(record){const files=[],sources=[];for(const d of descriptors(record)){const parsed=await inspect(d.archive);const archive={...d.archive,hash:parsed.archiveHash};sources.push({archive,index:parsed.index,phase:d.phase,ignoredTemporary:parsed.ignoredTemporary});for(const e of parsed.index)files.push({...e,archiveId:parsed.archiveHash,archive});}return{files,sources};}
 async function importFiles(files,record){const S=root.ProjectWorkspaceStore,R=root.WorkpaperRouting;if(files.length<1||files.length>7)throw Error('一次请选择1至7个本次底稿ZIP');const next={...(record.workpaperSources||{})},ignored=[];for(const file of files){if(!/\.zip$/i.test(file.name)||file.size>24*1024*1024)throw Error('请选择24MiB以内的底稿ZIP');const hash=await S.hash(file),known=R.identifyArchive(hash);if(!known)throw Error('原包不是本次提供的七份底稿包，未猜测套用，请核对文件版本。');const archive={name:file.name,hash,blob:file},parsed=await inspect(archive);next[hash]={archive,index:parsed.index,phase:phase(known.name),canonicalName:known.name};ignored.push(...parsed.ignoredTemporary);}return{patch:{workpaperSources:next},ignored};}
 async function importStage(file,record,stage){
  if(![5,6,7].includes(stage))throw Error('底稿阶段入口无效，未导入原包。');const expected=root.WorkpaperStages?.config(stage);if(!expected)throw Error('底稿阶段身份组件未加载，未导入原包。');
  if(!file||typeof file.name!=='string'||!/\.zip$/i.test(file.name)||!Number.isSafeInteger(file.size)||file.size<1||file.size>24*1024*1024)throw Error('请选择24MiB以内的准确阶段ZIP');
  const hash=await root.ProjectWorkspaceStore.hash(file),known=root.WorkpaperRouting.identifyArchive(hash);if(hash!==expected.sha256||!known||known.sha256!==expected.sha256||known.name!==expected.canonicalName)throw Error('此ZIP不是“'+expected.name+'”的准确原包，未改写或套用其他阶段。');
  return importFiles([file],record);
 }
 async function fileFor(target,prepared){const match=prepared.files.find(x=>x.path===target.path&&x.sha256===target.sha256);if(!match)throw Error('尚未导入此版本底稿原包，请先导入目录上方对应ZIP');const a=await root.BidderArchive.open(new File([match.archive.blob],match.archive.name),{entryLimit:2048});try{const bytes=(await a.read([target.path])).get(target.path);if(await root.ProjectWorkspaceStore.hash(new Blob([bytes]))!==target.sha256)throw Error('底稿原件哈希不一致，未打开错误版本');return{archive:match.archive,name:target.path,sha256:target.sha256,file:new File([bytes],target.path)};}finally{a.close();}}
 function script(path){if(!/^(?:workpaper-layouts|workpaper-word-layouts)\/[a-f0-9]{64}\.js$/.test(path))return Promise.reject(Error('底稿版式资源路径无效'));if(pending.has(path))return pending.get(path);const p=new Promise((ok,no)=>{const n=document.createElement('script');n.src=new URL(path,document.baseURI).href;n.onload=()=>{n.remove();ok();};n.onerror=()=>{n.remove();pending.delete(path);no(Error('底稿版式未能加载，请刷新后重试'));};document.head.append(n);});pending.set(path,p);return p;}
 async function layout(hash){let value=root.InitialLayoutCatalog?.[hash]||root.RiskLayoutCatalog?.[hash]||root.WorkpaperLayoutChunks?.[hash];if(value)return value;const path=root.WorkpaperLayoutManifest?.[hash];if(!path)return null;await script(path);return root.WorkpaperLayoutChunks?.[hash]||null;}
 async function word(hash){let value=root.InitialWordLayoutCatalog?.[hash]||root.RiskWordLayoutCatalog?.[hash]||root.WorkpaperWordLayoutChunks?.[hash];if(value)return value;const path=root.WorkpaperWordLayoutManifest?.[hash];if(!path)return null;await script(path);return root.WorkpaperWordLayoutChunks?.[hash]||null;}
 root.WorkpaperLibrary=Object.freeze({prepare,importFiles,importStage,fileFor,layout,word,descriptors});
})(globalThis);
